// Sophia Script for Windows launcher for WinGet
// https://github.com/farag2/Sophia-Script-for-Windows
//
// Extracts the embedded Sophia Script for Windows 11 archive to the Downloads folder and opens the extracted folder in File Explorer
// Built by Scripts\Building\WinGet_Launcher.ps1 with csc.exe from .NET Framework 4.x, so the code must stay C# 5 compatible
// Assembly attributes (product name, version) are generated by WinGet_Launcher.ps1

using System;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Windows.Forms;

namespace SophiaScript
{
	internal static class Launcher
	{
		// Name of the embedded resource with the release ZIP archive
		private const string ResourceName = "Sophia.zip";

		private const string Caption = "Sophia Script for Windows";

		// FOLDERID_Downloads
		// https://learn.microsoft.com/windows/win32/shell/knownfolderid
		private static readonly Guid DownloadsFolderId = new Guid("374DE290-123F-4565-9164-39C4925E467B");

		[DllImport("shell32.dll", CharSet = CharSet.Unicode, ExactSpelling = true)]
		private static extern int SHGetKnownFolderPath(ref Guid rfid, uint dwFlags, IntPtr hToken, out IntPtr ppszPath);

		[STAThread]
		private static int Main()
		{
			try
			{
				string downloadsFolder = GetDownloadsFolder();
				string sophiaFolder = ExtractArchive(downloadsFolder);

				Process.Start("explorer.exe", "\"" + sophiaFolder + "\"");

				return 0;
			}
			catch (Exception exception)
			{
				MessageBox.Show(exception.Message, Caption, MessageBoxButtons.OK, MessageBoxIcon.Error);

				return 1;
			}
		}

		// Get the actual Downloads folder path, even if the user moved it
		private static string GetDownloadsFolder()
		{
			Guid folderId = DownloadsFolderId;
			IntPtr pathPointer;

			int result = SHGetKnownFolderPath(ref folderId, 0, IntPtr.Zero, out pathPointer);
			try
			{
				if (result != 0)
				{
					throw Marshal.GetExceptionForHR(result);
				}

				return Marshal.PtrToStringUni(pathPointer);
			}
			finally
			{
				Marshal.FreeCoTaskMem(pathPointer);
			}
		}

		// Extract the embedded archive to the destination folder and return the full path of the archive's top-level folder
		private static string ExtractArchive(string destinationFolder)
		{
			string root = Path.GetFullPath(destinationFolder).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
			string topLevelFolder = null;

			Stream resource = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName);
			if (resource == null)
			{
				throw new InvalidOperationException("The embedded archive wasn't found.");
			}

			using (resource)
			using (ZipArchive archive = new ZipArchive(resource, ZipArchiveMode.Read))
			{
				foreach (ZipArchiveEntry entry in archive.Entries)
				{
					// Compress-Archive in Windows PowerShell 5.1 can write "\" instead of "/" in entry names
					string entryName = entry.FullName.Replace('\\', '/');

					if (topLevelFolder == null)
					{
						topLevelFolder = entryName.Split('/')[0];
					}

					// Don't let an entry be written outside the destination folder
					string destination = Path.GetFullPath(Path.Combine(root, entryName));
					if (!destination.StartsWith(root, StringComparison.OrdinalIgnoreCase))
					{
						throw new InvalidDataException("The archive contains an unsafe path: " + entry.FullName);
					}

					// Folder entry
					if (entryName.EndsWith("/", StringComparison.Ordinal))
					{
						Directory.CreateDirectory(destination);
						continue;
					}

					Directory.CreateDirectory(Path.GetDirectoryName(destination));
					entry.ExtractToFile(destination, true);
				}
			}

			if (string.IsNullOrEmpty(topLevelFolder))
			{
				throw new InvalidDataException("The embedded archive is empty.");
			}

			return Path.Combine(root, topLevelFolder);
		}
	}
}
